def _zapisat(put: Path, text: str, bak_suffix: str) -> bool:
    """Пишет с бэкапом и проверкой компиляции. Не компилируется — откат."""
    if _SUHO:
        return True
    bak = put.with_suffix(put.suffix + bak_suffix)
    if put.exists() and not bak.exists():
        shutil.copy2(put, bak)
    put.write_text(text, encoding="utf-8")
    if put.suffix == ".py":
        try:
            py_compile.compile(str(put), doraise=True)
        except py_compile.PyCompileError as e:
            if bak.exists():
                shutil.copy2(bak, put)
            сбой(f"{put.name}: не компилируется, откатил ({e})")
            return False
    return True


def v_arhiv(istochnik: Path, podpapka: str) -> bool:
    """Переносит в архив. Ничего не удаляем — всё возвращаемо."""
    if not istochnik.exists():
        return False
    kuda = ARHIV / podpapka / istochnik.name
    if kuda.exists():
        мимо(f"{istochnik.name} — в архиве уже лежит")
        return False
    if not _SUHO:
        kuda.parent.mkdir(parents=True, exist_ok=True)
        shutil.move(str(istochnik), str(kuda))
    ок(f"{istochnik.name} → _АРХИВ_ЧИСТКИ/{podpapka}/")
    return True


