def shag_knopka_vzglyad():
    шаг(2, "Убираю кнопку «взгляд» из кабинета (панель графика остаётся)")
    if not UI.exists():
        сбой(f"нет {UI}")
        return
    s = UI.read_text(encoding="utf-8")
    if "vzglyad_treydera" not in s:
        мимо("кнопки уже нет")
        return
    novyy = s
    for kusok, imya in ((FN_VZGLYAD, "код кнопки"), (BTN_VZGLYAD, "сама кнопка")):
        if novyy.count(kusok) != 1:
            сбой(f"{imya}: кусок не найден или не единственный — не трогаю файл")
            return
        novyy = novyy.replace(kusok, "", 1)
    try:
        ast.parse(novyy)
    except SyntaxError as e:
        сбой(f"после вырезания не разбирается: {e}")
        return
    if _zapisat(UI, novyy, ".bak_bez_vzglyada"):
        ок("кнопка и её код убраны")


