# 3. СЛОТЫ СЕНСОРОВ
# ════════════════════════════════════════════════════════════

def _cehi():
    if not CEHA.exists():
        return []
    return [d for d in sorted(CEHA.iterdir())
            if d.is_dir() and (d / "manifest.json").exists()]


def shag_slotry_sensorov():
    шаг(3, "Убираю слоты сенсоров A01–A04 (папка целиком + запись в манифесте)")
    tronuli = False
    for ceh in _cehi():
        mf = ceh / "manifest.json"
        m = json.loads(mf.read_text(encoding="utf-8"))
        bylo = [s.get("слот") for s in m.get("слоты", [])]
        ubrat = [s for s in SENSORY if s in bylo or (ceh / "слоты" / s).exists()]
        if not ubrat:
            continue
        for slot in ubrat:
            papka = ceh / "слоты" / slot
            if papka.exists():
                v_arhiv(papka, f"слоты/{ceh.name}")
                tronuli = True
        novye = [s for s in m.get("слоты", []) if s.get("слот") not in SENSORY]
        if len(novye) != len(m.get("слоты", [])):
            m["слоты"] = novye
            if not _SUHO:
                bak = mf.with_suffix(".json.bak_bez_sensorov")
                if not bak.exists():
                    shutil.copy2(mf, bak)
                mf.write_text(json.dumps(m, ensure_ascii=False, indent=2),
                              encoding="utf-8")
            ок(f"манифест цеха {ceh.name}: записи сенсоров убраны")
            tronuli = True
    if not tronuli:
        мимо("сенсоров в цехах уже нет")


