def shag_znaniya_faily():
    шаг(4, "Кладу знания трейдерам (разворотный бар, индикаторы, паттерны)")
    polozhili = 0
    for ceh in _cehi():
        for slot in TREYDERY:
            d = ceh / "слоты" / slot / "знания"
            if not (ceh / "слоты" / slot).exists():
                continue
            for imya, text in ZNANIYA.items():
                f = d / imya
                if f.exists():
                    continue
                if not _SUHO:
                    d.mkdir(parents=True, exist_ok=True)
                    f.write_text(text, encoding="utf-8")
                polozhili += 1
    if polozhili:
        ок(f"положено файлов: {polozhili}")
    else:
        мимо("знания уже на месте")


