Z_OLD = 'KNOWLEDGE    = _SLOT_DIR / "знания" / "KOTIN_PHILOSOPHY.md"'
Z_NEW = '''# ZNANIYA_PAPKOY_V1: канон — «слот несёт с собой знания/», ПАПКУ.
# Было прибито одно имя файла, и второй файл в папке не читался никем.
KNOWLEDGE_DIR = _SLOT_DIR / "знания"
KNOWLEDGE    = KNOWLEDGE_DIR / "KOTIN_PHILOSOPHY.md"   # оставлено для совместимости


def _znaniya_roli() -> str:
    """Вся база знаний роли — все .md и .txt из папки, по алфавиту.

    Каждый источник под своим заголовком: роль должна понимать, где
    кончается один и начинается другой, иначе всё сливается в кашу.
    """
    if not KNOWLEDGE_DIR.exists():
        return ""
    kuski = []
    for f in sorted(KNOWLEDGE_DIR.iterdir()):
        if f.is_file() and f.suffix.lower() in (".md", ".txt"):
            try:
                kuski.append(f"\\n\\n===== {f.stem} =====\\n"
                             + f.read_text(encoding="utf-8"))
            except Exception:
                pass
    return "".join(kuski)'''

Z2_OLD = 'knowledge = KNOWLEDGE.read_text(encoding="utf-8") if KNOWLEDGE.exists() else ""'
Z2_NEW = 'knowledge = _znaniya_roli()   # ZNANIYA_PAPKOY_V1: вся папка, не один файл'


def shag_znaniya_papkoy():
    шаг(5, "Учу мозги читать знания папкой, а не одним файлом")
    pravleno = uzhe = 0
    for mozg in sorted(CEHA.glob("*/слоты/*/мозг.py")) if CEHA.exists() else []:
        s = mozg.read_text(encoding="utf-8")
        if "ZNANIYA_PAPKOY_V1" in s:
            uzhe += 1
            continue
        if s.count(Z_OLD) != 1 or s.count(Z2_OLD) != 1:
            continue
        novyy = s.replace(Z_OLD, Z_NEW, 1).replace(Z2_OLD, Z2_NEW, 1)
        try:
            ast.parse(novyy)
        except SyntaxError as e:
            сбой(f"{mozg.parent.name}: {e}")
            continue
        if _zapisat(mozg, novyy, ".bak_znaniya_papkoy"):
            pravleno += 1
    if pravleno:
        ок(f"мозгов поправлено: {pravleno}")
    if uzhe and not pravleno:
        мимо(f"уже умеют ({uzhe})")


