def shag_sostav_s_diska():
    шаг(6, "Состав кабинета читается с диска (вбитый список убирается)")
    if not UI.exists():
        сбой(f"нет {UI}")
        return
    s = UI.read_text(encoding="utf-8")
    if "SOSTAV_S_DISKA_V1" in s:
        мимо("уже читается с диска")
        return
    novyy = s
    # заодно правим упоминание в шапке файла — иначе комментарий будет
    # обещать список, которого больше нет
    novyy = novyy.replace(
        "  ROSTER_SPEC ниже сводит оба цеха в один хедер, порядок и иконки —",
        "  Состав читается из манифестов цехов (SOSTAV_S_DISKA_V1), иконки —", 1)
    for imya, old, new in (("список агентов", ROSTER_OLD, R_NEW),
                           ("активный вначале", ACTIVE_OLD, A_NEW),
                           ("сборка состава", B_OLD, B_NEW),
                           ("первый активный", P_OLD, P_NEW)):
        if novyy.count(old) != 1:
            сбой(f"«{imya}»: кусок найден {novyy.count(old)} раз — "
                 f"файл не тот, ничего не меняю")
            return
        novyy = novyy.replace(old, new, 1)
    try:
        ast.parse(novyy)
    except SyntaxError as e:
        сбой(f"после правки не разбирается: {e}")
        return
    if _zapisat(UI, novyy, ".bak_sostav_s_diska"):
        ок("кабинет собирает состав из манифестов")


