def pokazat_sostav():
    print("\n" + "─" * 58)
    print("КТО ТЕПЕРЬ В КВАРТАЛЕ (так его увидит кабинет):")
    IK = {"A06": "🪨", "A07": "🎲", "A08": "⚖️",
          "архивариус": "📚", "исполнитель": "🎬"}
    ST = {"архивариус": "A05", "исполнитель": "A09"}
    ceha = []
    for c in _cehi():
        m = json.loads((c / "manifest.json").read_text(encoding="utf-8"))
        m["id"] = c.name
        m["_путь"] = c
        ceha.append(m)
    shtaby = {c.get("штаб") for c in ceha if c.get("штаб")}
    ceha.sort(key=lambda c: (1 if c["id"] in shtaby else 0, c["id"]))
    pusto = True
    for c in ceha:
        for s in c.get("слоты", []):
            sl = s.get("слот", "")
            if not (c["_путь"] / "слоты" / sl / "мозг.py").exists():
                continue
            pusto = False
            print(f"   {IK.get(sl, '🎓')} {ST.get(sl, sl):12} "
                  f"{s.get('роль', ''):18} цех {c['id']}")
    if pusto:
        print("   (никого — но кабинет от этого не падает)")


def main() -> int:
    global _SUHO
    ap = argparse.ArgumentParser()
    ap.add_argument("--suho", action="store_true",
                    help="показать, что будет сделано, и ничего не делать")
    a = ap.parse_args()
    _SUHO = a.suho

    if not BIRZHA.exists() or not CEHA.exists():
        print("✗ это не корень репо: не вижу папок Биржа/ и GRONDHEIM_CITY/")
        return 1

    print("═" * 58)
    print("НАСТРОЙКА БИРЖИ" + ("   [СУХОЙ ПРОГОН — ничего не пишу]" if _SUHO else ""))
    print("═" * 58)

    shag_lishnie_faily()
    shag_knopka_vzglyad()
    shag_slotry_sensorov()
    shag_znaniya_faily()
    shag_znaniya_papkoy()
    shag_sostav_s_diska()

    pokazat_sostav()

    print("\n" + "─" * 58)
    print(f"сделано: {len(_SDELANO)}   пропущено (уже было): {len(_PROPUSK)}"
          f"   сбоев: {len(_SBOI)}")
    if _SBOI:
        print("\nСБОИ — разобрать:")
        for x in _SBOI:
            print(f"   ✗ {x}")
        print("\nФайлы при сбое НЕ менялись, рядом с каждым правленым лежит .bak")
    if _SUHO:
        print("\nЭто был сухой прогон. Запусти без --suho, чтобы сделать.")
    else:
        print("\nНичего не удалено: всё убранное лежит в _АРХИВ_ЧИСТКИ/")
    return 1 if _SBOI else 0


if __name__ == "__main__":
    sys.exit(main())
